from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int], workers: int = 4) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel with a
    thread pool of `workers` threads. Results are in input order, regardless
    of the worker count. Negative numbers give 0 or 1 (Python modulo).
    Raises ValueError if workers < 1."""
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return list(pool.map(parity, xs))


def test_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_empty() -> None:
    assert parities([]) == []


def test_negative_and_zero() -> None:
    assert parities([-3, -2, 0, 7]) == [1, 0, 0, 1]


def test_large_ints() -> None:
    assert parities([2**100, 2**100 + 1]) == [0, 1]


def test_order_preserved_large_input() -> None:
    xs = list(range(1000))
    assert parities(xs) == [parity(x) for x in xs]


@pytest.mark.parametrize("workers", [1, 2, 3, 8, 64])
def test_independent_of_worker_count(workers: int) -> None:
    xs = [5, 8, -1, 0, 13, 22, 7, 100, 101]
    assert parities(xs, workers=workers) == [parity(x) for x in xs]


def test_more_workers_than_items() -> None:
    assert parities([1, 2], workers=32) == [1, 0]


def test_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        parities([1, 2, 3], workers=workers)

